823	/**
824	 *
825	 * Set element as highlight / downplay dispatcher.
826	 * It will be checked when element received mouseover event or from highlight action.
827	 * It's in change of all highlight/downplay behavior of it's children.
828	 *
829	 * @param el
830	 * @param el.highDownSilentOnTouch
831	 *        In touch device, mouseover event will be trigger on touchstart event
832	 *        (see module:zrender/dom/HandlerProxy). By this mechanism, we can
833	 *        conveniently use hoverStyle when tap on touch screen without additional
834	 *        code for compatibility.
835	 *        But if the chart/component has select feature, which usually also use
836	 *        hoverStyle, there might be conflict between 'select-highlight' and
837	 *        'hover-highlight' especially when roam is enabled (see geo for example).
838	 *        In this case, `highDownSilentOnTouch` should be used to disable
839	 *        hover-highlight on touch device.
840	 * @param asDispatcher If `false`, do not set as "highDownDispatcher".
841	 */
842	export function setAsHighDownDispatcher(el: Element, asDispatcher: boolean) {
843	    const disable = asDispatcher === false;
844	    const extendedEl = el as ExtendedElement;
845	    // Make `highDownSilentOnTouch` and `onStateChange` only work after
846	    // `setAsHighDownDispatcher` called. Avoid it is modified by user unexpectedly.
847	    if ((el as ECElement).highDownSilentOnTouch) {
848	        extendedEl.__highDownSilentOnTouch = (el as ECElement).highDownSilentOnTouch;
849	    }
850	    // Simple optimize, since this method might be
851	    // called for each elements of a group in some cases.
852	    if (!disable || extendedEl.__highDownDispatcher) {
853	        // Emphasis, normal can be triggered manually by API or other components like hover link.
854	        // el[method]('emphasis', onElementEmphasisEvent)[method]('normal', onElementNormalEvent);
855	        // Also keep previous record.
856	        extendedEl.__highByOuter = extendedEl.__highByOuter || 0;
857	        extendedEl.__highDownDispatcher = !disable;
858	    }
859	}
860	
861	export function isHighDownDispatcher(el: Element): boolean {
862	    return !!(el && (el as ExtendedDisplayable).__highDownDispatcher);
863	}
