310	// Provide setColor helper method to avoid determine if set the fill or stroke outside
311	function symbolPathSetColor(this: ECSymbol, color: ZRColor, innerColor?: ZRColor) {
312	    if (this.type !== 'image') {
313	        const symbolStyle = this.style;
314	        if (this.__isEmptyBrush) {
315	            symbolStyle.stroke = color;
316	            symbolStyle.fill = innerColor || tokens.color.neutral00;
317	            // TODO Same width with lineStyle in LineView
318	            symbolStyle.lineWidth = 2;
319	        }
320	        else if (this.shape.symbolType === 'line') {
321	            symbolStyle.stroke = color;
322	        }
323	        else {
324	            symbolStyle.fill = color;
325	        }
326	        this.markRedraw();
327	    }
328	}
